      "icon": "⚑",
      "symbol": "/AleriaAlmanach/assets/schwarze-zitteraale/groups/icons/icon-sumpfnattern-v1.png",
      "image": "/AleriaAlmanach/assets/schwarze-zitteraale/groups/banners/banner-sumpfnattern-v1.png",
